/**
 * Company Schema for Multi-Tenant Architecture
 * Defines the structure for company data in Firestore
 */

const CompanySchema = {
    // Unique identifier (auto-generated by Firestore)
    companyId: String,

    // Company Information
    companyName: String,
    companyEmail: String,
    companyLogo: String, // URL to Firebase Storage
    companyBanner: String, // URL to Banner Image
    themeColor: String, // Hex color for branding
    companyWebsite: String, // Optional

    // Admin & Access
    adminUserId: String, // Reference to users/{userId}
    voucherCode: String, // Unique voucher code for employee signup
    slug: String, // Unique URL slug for invite links (e.g., /acme-corp/register)

    // Subscription Management
    subscriptionStartDate: Date,
    subscriptionEndDate: Date, // 1 year from start
    status: String, // 'active' | 'expired' | 'suspended'

    // Settings
    settings: {
        lockBranding: Boolean, // If true, employees must use company logo
        allowLeadCapture: Boolean, // Enable lead capture features
        customDomain: String, // Optional custom domain
    },

    // Metadata
    createdAt: Date,
    updatedAt: Date,
};

/**
 * Validation rules for Company creation
 */
const validateCompany = (companyData) => {
    const errors = [];

    if (!companyData.companyName || companyData.companyName.trim().length < 2) {
        errors.push('Company name must be at least 2 characters');
    }

    if (!companyData.companyEmail || !isValidEmail(companyData.companyEmail)) {
        errors.push('Valid company email is required');
    }

    if (!companyData.adminUserId) {
        errors.push('Admin user ID is required');
    }

    if (!companyData.slug || companyData.slug.length < 3) {
        errors.push('Company slug must be at least 3 characters');
    }

    return errors;
};

/**
 * Helper function to validate email
 */
const isValidEmail = (email) => {
    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    return emailRegex.test(email);
};

/**
 * Default company settings
 */
const defaultSettings = {
    lockBranding: false,
    allowLeadCapture: true,
    customDomain: null,
};

export default {
    CompanySchema,
    validateCompany,
    defaultSettings,
};
